package com.mantou.salesdialer.contacts;
import android.app.Activity;import android.os.Bundle;import android.widget.*;
public final class PilotLauncherActivity extends Activity {
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(32,48,32,32);setContentView(body);TextView title=new TextView(this);title.setText("销售拨号·受控试点\n通过企业账号与自动队列连接电脑企业服务（USB或已配对Wi-Fi）。真实通话验证默认关闭。\n下方本机名单与通话页保留为旧资料/选卡诊断，不使用旧身份拨号。");body.addView(title);Button enterprise=new Button(this);enterprise.setText("企业账号与自动队列");body.addView(enterprise);enterprise.setOnClickListener(v->startActivity(new android.content.Intent(this,EnterpriseActivity.class)));Button connection=new Button(this);connection.setText("电脑连接设置（Wi-Fi / USB）");body.addView(connection);connection.setOnClickListener(v->startActivity(new android.content.Intent(this,EnterpriseConnectionActivity.class)));TextView status=new TextView(this);body.addView(status);Button list=new Button(this);list.setText("我的名单与计划");body.addView(list);Button call=new Button(this);call.setText("受控通话与结果");body.addView(call);Button check=new Button(this);check.setText("检查准备状态");body.addView(check);check.setEnabled(false);check.setOnClickListener(v->startActivity(new android.content.Intent(this,PilotReadinessCheckActivity.class)));list.setEnabled(false);call.setEnabled(false);list.setOnClickListener(v->startActivity(new android.content.Intent(this,PhoneIntakeActivity.class)));call.setOnClickListener(v->startActivity(new android.content.Intent(this,PilotActivity.class)));new Thread(()->{try{PilotPhoneRuntime.stopAll(getApplicationContext());runOnUiThread(()->{status.setText("旧许可已关闭，旧计划已暂停；名单和历史保留。");list.setEnabled(true);call.setEnabled(true);check.setEnabled(true);});}catch(Exception e){runOnUiThread(()->status.setText("读取或暂停失败，已停止。请保留数据检查。"));}},"pilot-open").start();}
}
